/* images.js — todas as fotos do site em um único arquivo.
   Cada imagem é aplicada na sua posição do HTML por meio de variáveis CSS:
   --img      -> foto da Dra. Marcela (seções Hero e Sobre)
   --g1..--g7 -> fotos da Galeria (carrossel, miniaturas e modal) */
(function () {
  var IMAGES = {
    doutora:
      "data:image/jpeg;base64,",
    galeria1:
      "data:image/jpeg;base64,",
    galeria2:
      "data:image/jpeg;base64,",
    galeria3:
      "data:image/jpeg;base64,",
    galeria4:
      "data:image/jpeg;base64,",
    galeria5:
      "data:image/jpeg;base64,",
    galeria6:
      "data:image/jpeg;base64,",
    galeria7:
      "data:image/jpeg;base64,",
  };
  var root = document.documentElement.style;
  root.setProperty("--img", 'url("' + IMAGES.doutora + '")');
  for (var k = 1; k <= 7; k++)
    root.setProperty("--g" + k, 'url("' + IMAGES["galeria" + k] + '")');
  window.IMAGES = IMAGES;
})();
